+/**
+ * Send a cron webhook while enforcing SSRF guard.
+ * This wraps fetchWithSsrFGuard and gives a consistent handling for SSRF-blocked targets.
+ * Keep this function minimal — callers expect it to throw for non-SSRF errors.
+ */
+async function sendCronWebhook(url: string, init: RequestInit & { timeoutMs?: number } = {}) {
+  // honor optional timeoutMs with AbortController (common pattern used elsewhere)
+  const timeoutMs = init.timeoutMs ?? CRON_WEBHOOK_TIMEOUT_MS;
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), timeoutMs);
+  try {
+    const opts: RequestInit = { ...init, signal: controller.signal };
+    // use the SSRF-guarded fetch implementation so cron webhooks cannot reach
+    // internal/private/metadata endpoints bypassing policy checks.
+    return await fetchWithSsrFGuard(url, opts);
+  } finally {
+    clearTimeout(timeout);
