+/*
+ * Minimal SVG sanitizer to mitigate stored XSS via uploaded SVG files.
+ * - Removes <script> elements
+ * - Strips inline event handler attributes (on*)
+ * - Neutralizes javascript: URIs in href/xlink:href attributes
+ *
+ * This is intentionally small and defensive. For more comprehensive
+ * sanitization consider integrating a dedicated SVG sanitizer library.
+ */
+function sanitizeSvg(svgSource) {
+  if (!svgSource || typeof svgSource !== 'string') return svgSource;
+
+  let svg = svgSource;
+
+  // Remove <script>...</script> blocks (case-insensitive, multi-line)
+  svg = svg.replace(/<script[\s\S]*?>[\s\S]*?<\/script\s*>/gi, '');
+
+  // Remove XML/HTML comments (they may hide scripts in some cases)
+  svg = svg.replace(/<!--[\s\S]*?-->/g, '');
+
+  // Strip inline event handler attributes: onload="...", onclick='...' etc.
+  // This removes attributes like on*, allowing small whitespace variations.
+  svg = svg.replace(/\s(on[a-z]+\s*=\s*"[^"]*")/gi, '');
+  svg = svg.replace(/\s(on[a-z]+\s*=\s*'[^']*')/gi, '');
+  // Also handle unquoted attributes (rare in well-formed SVG but defensive)
+  svg = svg.replace(/\s(on[a-z]+\s*=\s*[^\s>]+)/gi, '');
+
+  // Neutralize javascript: URIs in href and xlink:href attributes by replacing
+  // the value with a safe placeholder ("#"). Handles both single and double quotes.
+  svg = svg.replace(/(\s(?:href|xlink:href)\s*=\s*")\s*javascript:[^"]*"/gi, '$1#"');
+  svg = svg.replace(/(\s(?:href|xlink:href)\s*=\s*')\s*javascript:[^']*'/gi, "$1#'");
+  // Also neutralize unquoted href values starting with javascript:
+  svg = svg.replace(/(\s(?:href|xlink:href)\s*=\s*)javascript:[^\s>]+/gi, '$1"#"');
+
+  return svg;
+}
+
+module.exports = sanitizeSvg;
+
