+export const REDISEARCH_SPECIAL_CHARS = /([\-.\<\>\{\}\[\]"':;!@#\$%\^&\*\(\)\+\=\~\|\\\?\/])/g;
+
+/**
+ * Escape RediSearch special characters used in TAG queries so that user-controlled
+ * input cannot inject operators or change query structure.
+ *
+ * This prefixes each special character with a backslash, which makes RediSearch
+ * treat it as a literal character in tag queries.
+ */
+export function escapeRediSearchTagValue(value: string): string {
+  if (value == null) return "";
+  return String(value).replace(REDISEARCH_SPECIAL_CHARS, "\\$1");
+}
+
+/**
+ * Escape field/key used in RediSearch @field selectors.
+ * Field names rarely contain special characters, but escaping is harmless and prevents
+ * deliberate attempts to break the generated query.
+ */
+export function escapeRediSearchFieldName(field: string): string {
+  if (field == null) return "";
+  return String(field).replace(REDISEARCH_SPECIAL_CHARS, "\\$1");
