+function normalizeIpString(raw?: string | null): string {
+	if (!raw) return '';
+
+	let ip = raw.trim();
+
+	// strip IPv6 zone id, e.g. "fe80::1%eth0" -> "fe80::1"
+	const zoneIndex = ip.indexOf('%');
+	if (zoneIndex !== -1) {
+		ip = ip.substring(0, zoneIndex);
+	}
+
+	// strip surrounding brackets often used for IPv6 in URLs: "[::1]" -> "::1"
+	if (ip.startsWith('[') && ip.endsWith(']')) {
+		ip = ip.substring(1, ip.length - 1);
+	}
+
+	// normalize IPv4-mapped IPv6 addresses: "::ffff:127.0.0.1" -> "127.0.0.1"
+	const mappedPrefix = '::ffff:';
+	if (ip.toLowerCase().startsWith(mappedPrefix)) {
+		ip = ip.substring(mappedPrefix.length);
+	}
+
+	return ip;
+}
+
+export function isIpWhitelisted(ip: string, whitelist?: string[] | null): boolean {
+	if (!whitelist || whitelist.length === 0) {
+		// nothing configured -> allow by default
+		return true;
+	}
+
+	const normalizedIp = normalizeIpString(ip);
+
+	for (const entry of whitelist) {
+		if (!entry) continue;
+
+		const normalizedEntry = normalizeIpString(entry);
+
+		// perform exact match on normalized representations to avoid substring bypasses
+		if (normalizedIp === normalizedEntry) {
+			return true;
+		}
+	}
+
+	return false;
+}
