+const {BadRequestError} = require('../../../errors');
+
+// NOTE: this endpoint used raw SQL construction which allowed values from the
+// Admin API to be injected into the query string. That led to SQL Injection.
+// The code below previously concatenated user-supplied values directly into
+// SQL; it now uses parameterized queries via knex.raw bindings.
+
+const getEvents = async function (options) {
+    const knex = require('../../../models').knex;
+
+    const {event = 'signup', from, to, actor_id: actorId} = options;
+
+    if (!event) {
+        throw new BadRequestError({message: 'Missing event type'});
+    }
+
+    // Build SQL with parameter placeholders and a bindings array to avoid
+    // interpolating user-supplied values directly into the query string.
+    const bindings = [];
+    let sql = `
+        SELECT e.id, e.type, e.created_at, e.actor_id, e.data
+        FROM members_events e
+        WHERE e.type = ?
+    `;
+    bindings.push(event);
+
+    if (from) {
+        sql += ` AND e.created_at >= ?`;
+        bindings.push(from);
+    }
+
+    if (to) {
+        sql += ` AND e.created_at <= ?`;
+        bindings.push(to);
+    }
+
+    if (actorId) {
+        sql += ` AND e.actor_id = ?`;
+        bindings.push(actorId);
+    }
+
+    sql += ' ORDER BY e.created_at DESC';
+
+    const results = await knex.raw(sql, bindings);
+    // knex.raw on different adapters returns different shapes; keep previous
+    // behavior by returning rows when available, otherwise the raw result.
+    return results.rows || results;
+};
