+// The token request cache may be used concurrently across multiple incoming
+// requests when the SDK is instantiated as a singleton. To avoid cross-request
+// lookup collisions, prefer a request-scoped cache (WeakMap keyed by the
+// IncomingMessage/Request object) when a request object is available. Fall
+// back to a global cache when no request is provided to maintain backwards
+// compatibility.
+const globalTokenRequestCache = new Map<string, any>();
+const requestScopedTokenRequestCaches = typeof WeakMap !== 'undefined' ? new WeakMap<any, Map<string, any>>() : null;
+
+function cacheForRequest(req?: any): Map<string, any> {
+  if (req && requestScopedTokenRequestCaches) {
+    let map = requestScopedTokenRequestCaches.get(req);
+    if (!map) {
+      map = new Map<string, any>();
+      requestScopedTokenRequestCaches.set(req, map);
+    }
+    return map;
+  }
+  return globalTokenRequestCache;
+}
+
+export const TokenRequestCache = {
+  // Optional request parameter: when provided we scope the cache to that
+  // particular request to prevent simultaneous requests from colliding.
+  get<T = any>(key: string, req?: any): T | undefined {
+    return cacheForRequest(req).get(key);
+  },
+
+  set<T = any>(key: string, value: T, req?: any): void {
+    cacheForRequest(req).set(key, value);
+  },
+
+  delete(key: string, req?: any): void {
