+export function redirectToAuthorization(authorizationUrl: string): void {
+  if (!authorizationUrl) return;
+
+  // Basic type check
+  if (typeof authorizationUrl !== 'string') {
+    throw new TypeError('authorizationUrl must be a string');
+  }
+
+  // Reject obviously malicious / non-printable input (nulls, newlines, control chars)
+  if (/[^\t\n\r\x20-\x7E]/.test(authorizationUrl) || /\r|\n/.test(authorizationUrl)) {
+    throw new Error('Invalid URL');
+  }
+
+  // Ensure we have a valid absolute HTTP(S) URL
+  let parsed: URL;
+  try {
+    parsed = new URL(authorizationUrl);
+  } catch {
+    throw new Error('Invalid URL');
+  }
+  if (!['http:', 'https:'].includes(parsed.protocol)) {
+    throw new Error('Invalid URL protocol');
+  }
+
+  const platform = process.platform;
+  let cmd: string;
+  let args: string[];
+
+  if (platform === 'win32') {
