+// Robust check for localhost / loopback addresses
+// Accepts hostnames with optional ports and handles:
+//  - "localhost"
+//  - IPv4 loopback range 127.0.0.0/8 (e.g. 127.0.0.1, 127.0.0.2, ...)
+//  - IPv6 loopback ::1
+//  - IPv4-mapped IPv6 addresses like ::ffff:127.0.0.1
+export function isLocalhost(host: string | undefined) {
+  if (!host) return false;
+  // Strip any trailing port (e.g. "127.0.0.1:8080")
+  const raw = host.split(':')[0].toLowerCase();
+
+  if (raw === 'localhost' || raw === '::1') return true;
+
+  // IPv4-mapped IPv6 like ::ffff:127.0.0.1
+  if (raw.startsWith('::ffff:')) {
+    const v4 = raw.substring('::ffff:'.length);
+    const octets = v4.split('.');
+    if (octets.length === 4) {
+      return octets[0] === '127';
+    }
+    return false;
+  }
+
+  // IPv4 addresses: treat any 127.*.*.* as loopback (127.0.0.0/8)
+  const parts = raw.split('.');
+  if (parts.length === 4) {
+    // Only check first octet for 127/8; other octets may be any valid number 0-255.
+    return parts[0] === '127';
+  }
+
+  return false;
