+import { SessionStore } from "./store";
+
+export interface Session {
+  id: string;
+  data: Record<string, unknown>;
+  // ISO string or epoch milliseconds
+  expiresAt?: string | number;
+}
+
+function isExpired(session: Session): boolean {
+  if (!session?.expiresAt) return false;
+  const expires = typeof session.expiresAt === "number"
+    ? session.expiresAt
+    : Date.parse(String(session.expiresAt));
+  if (Number.isNaN(expires)) return false;
+  return Date.now() > expires;
+}
+
+/**
+ * Retrieve a session from the underlying store.
+ *
+ * If a session exists but is expired, remove it from the store and return null.
+ * This prevents a client from reusing an expired session (for example via the
+ * x-workos-session header).
+ */
+export async function getSession(store: SessionStore, id: string): Promise<Session | null> {
+  const session = (await store.get(id)) as Session | null;
+  if (!session) return null;
+
+  if (isExpired(session)) {
+    // Best-effort cleanup of expired session to avoid reuse.
+    // Some store implementations may not implement delete; ignore errors.
+    try {
+      // eslint-disable-next-line @typescript-eslint/no-explicit-any
+      if (typeof (store as any).delete === "function") {
+        await (store as any).delete(id);
+      }
+    } catch {
+      // swallow - cleanup is best-effort
+    }
+    return null;
+  }
+
+  return session;
+}
