+// Minimal HTML sanitizer to mitigate XSS when rendering rich text content.
+// This is intentionally small and conservative: it removes potentially dangerous
+// elements (script/style/iframe/object/embed/link/meta) and strips attributes
+// that can execute code (on* handlers, javascript: / vbscript: URIs, data: URIs
+// on src/href). For environments without DOMParser (SSR), a simple script tag
+// removal fallback is applied.
+export default function sanitizeHtml(html: string): string {
+    if (!html) {
+        return html;
+    }
+
+    // Fallback for non-browser environments (basic script tag removal).
+    if (typeof window === "undefined" || typeof DOMParser === "undefined") {
+        return html.replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "");
+    }
+
+    const parser = new DOMParser();
+    const doc = parser.parseFromString(html, "text/html");
+
+    // Remove entire elements that can load/execute external or inline content.
+    const forbiddenTags = ["script", "style", "iframe", "object", "embed", "link", "meta"];
+    forbiddenTags.forEach((tag) => {
+        const nodes = doc.getElementsByTagName(tag);
+        // HTMLCollection is live; convert to array first.
+        Array.from(nodes).forEach((n) => n.parentNode && n.parentNode.removeChild(n));
+    });
+
+    // Walk elements and remove dangerous attributes.
+    const walker = doc.createTreeWalker(doc.body, NodeFilter.SHOW_ELEMENT, null);
+    let current: Node | null = walker.nextNode();
+    while (current) {
+        const el = current as Element;
+        const attrs = Array.from(el.attributes);
+        attrs.forEach((attr) => {
+            const name = attr.name.toLowerCase();
+            const value = (attr.value || "").trim().toLowerCase();
+
+            // Remove event handlers like onclick, onerror, etc.
+            if (name.startsWith("on")) {
+                el.removeAttribute(attr.name);
+                return;
+            }
+
+            // Remove javascript: and vbscript: URIs.
+            if (value.startsWith("javascript:") || value.startsWith("vbscript:")) {
+                el.removeAttribute(attr.name);
+                return;
+            }
+
+            // Disallow data: URIs for src/href since they can include base64 JS in some contexts.
+            if ((name === "src" || name === "href") && value.startsWith("data:")) {
+                el.removeAttribute(attr.name);
+                return;
+            }
+        });
+
+        current = walker.nextNode();
+    }
+
+    return doc.body.innerHTML;
