+/**
+ * Middleware to apply `filter` and `filterout` query parameters safely.
+ *
+ * This implementation avoids creating RegExp from untrusted input unless
+ * explicitly requested (pattern enclosed by slashes). It also imposes
+ * limits on the number of filters and pattern lengths to mitigate ReDoS /
+ * high CPU risks (CVE-2022-31110).
+ */
+'use strict';
+
+const MAX_FILTERS = 10;        // maximum number of ';' separated filters
+const MAX_PATTERN_LEN = 200;   // max length of each pattern string
+const MAX_REGEX_BODY = 100;    // max length of regex body when using /.../
+
+function parseFilterString(raw) {
+    if (!raw || typeof raw !== 'string') return [];
+
+    const parts = raw.split(';').map(p => p.trim()).filter(Boolean);
+    if (parts.length === 0) return [];
+    if (parts.length > MAX_FILTERS) {
+        // keep only the first MAX_FILTERS items
+        parts.length = MAX_FILTERS;
+    }
+
+    const res = [];
+    for (const part of parts) {
+        if (part.length > MAX_PATTERN_LEN) {
+            // skip overly long pattern
+            continue;
+        }
+
+        // If pattern is explicitly a regex: /pattern/flags
+        if (part[0] === '/' && part.lastIndexOf('/') > 0) {
+            const lastSlash = part.lastIndexOf('/');
+            const body = part.slice(1, lastSlash);
+            const flags = part.slice(lastSlash + 1);
+
+            // protect against overly long regex bodies
+            if (body.length > MAX_REGEX_BODY) {
+                // skip suspiciously long regex
+                continue;
+            }
