+            try {
+                // Only allow a small set of flags; default to 'i' if none provided
+                const allowedFlags = (flags || 'i').replace(/[^gimuys]/g, '');
+                const safeFlags = allowedFlags.includes('i') ? allowedFlags : (allowedFlags + 'i');
