+                res.push({ type: 'regex', value: re });
+                continue;
+            } catch (e) {
+                // If regex compilation fails, fall back to literal match
+                // (do not throw — be tolerant)
+            }
+        }
+
+        // Plain substring match (case-insensitive)
+        res.push({ type: 'substr', value: part.toLowerCase() });
