+import dns from 'dns';
+import net from 'net';
+
+const { lookup } = dns.promises;
+
+function ipv4ToInt(ip: string) {
+  return ip.split('.').reduce((acc, octet) => (acc << 8) + Number(octet), 0) >>> 0;
+}
+
+function isPrivateIPv4(ip: string) {
+  const i = ipv4ToInt(ip);
+
+  // 10.0.0.0/8
+  if ((i & 0xff000000) === 0x0a000000) return true;
+  // 172.16.0.0/12
+  if ((i & 0xfff00000) === 0xac100000) return true;
+  // 192.168.0.0/16
+  if ((i & 0xffff0000) === 0xc0a80000) return true;
+  // 127.0.0.0/8 loopback
+  if ((i & 0xff000000) === 0x7f000000) return true;
+  // 169.254.0.0/16 link-local
+  if ((i & 0xffff0000) === 0xa9fe0000) return true;
+  // 0.0.0.0/8
+  if ((i & 0xff000000) === 0x00000000) return true;
+  // 100.64.0.0/10 carrier-grade NAT
+  if ((i & 0xffc00000) === 0x64400000) return true;
+  return false;
+}
+
+function isPrivateIPv6(ip: string) {
+  // Normalize IPv6 zones, and check known private ranges:
+  // - loopback ::1
+  // - unique local fc00::/7
+  // - link-local fe80::/10
+  if (ip === '::1') return true;
+  const lower = ip.toLowerCase();
+  if (lower.startsWith('fc') || lower.startsWith('fd')) return true;
+  if (lower.startsWith('fe80') || lower.startsWith('fe8') || lower.startsWith('fe9') || lower.startsWith('fea') || lower.startsWith('feb')) return true;
+  return false;
+}
+
+export async function validateRemoteUrlAllowlist(rawUrl: string) {
+  let parsed: URL;
+  try {
+    parsed = new URL(rawUrl);
+  } catch (err) {
+    throw new Error('Invalid URL');
+  }
+
+  const protocol = parsed.protocol.replace(':', '');
+  if (!['http', 'https'].includes(protocol)) {
+    throw new Error('Invalid protocol');
+  }
+
+  const hostname = parsed.hostname;
+
+  // Block obvious hostnames
+  if (!hostname || hostname.toLowerCase() === 'localhost') {
+    throw new Error('Access to local or unspecified host is forbidden');
+  }
+
+  // If hostname is a literal IP, check immediately
+  if (net.isIP(hostname)) {
+    if (net.isIPv4(hostname) && isPrivateIPv4(hostname)) {
+      throw new Error('Access to private IP ranges is forbidden');
+    }
+    if (net.isIPv6(hostname) && isPrivateIPv6(hostname)) {
+      throw new Error('Access to private IP ranges is forbidden');
+    }
+    return;
+  }
+
+  // Resolve hostname to all addresses and ensure none are private
+  let addresses;
+  try {
+    addresses = await lookup(hostname, { all: true });
+  } catch (err) {
+    // If DNS resolution fails treat as unreachable (fail fast)
+    throw new Error('Could not resolve remote host');
+  }
+
+  if (!addresses || addresses.length === 0) {
+    throw new Error('Could not resolve remote host');
+  }
+
+  for (const addr of addresses) {
+    const ip = addr.address;
+    if (net.isIPv4(ip) && isPrivateIPv4(ip)) {
+      throw new Error('Access to private IP ranges is forbidden');
+    }
+    if (net.isIPv6(ip) && isPrivateIPv6(ip)) {
+      throw new Error('Access to private IP ranges is forbidden');
+    }
+  }
+}
