+import http from 'http';
+import https from 'https';
+import { pipeline } from 'stream';
+import { promisify } from 'util';
+import { URL } from 'url';
+import { validateRemoteUrlAllowlist } from '../utils/validate-remote-url';
+
+const streamPipeline = promisify(pipeline);
+
+export async function downloadRemoteFile(remoteUrl: string, writableStream) {
+  // Validate the remote URL to prevent SSRF against internal networks.
+  await validateRemoteUrlAllowlist(remoteUrl);
+
+  const url = new URL(remoteUrl);
+
+  const get = url.protocol === 'https:' ? https.get : http.get;
+
+  return new Promise((resolve, reject) => {
+    const req = get(remoteUrl, (res) => {
+      if (res.statusCode && (res.statusCode < 200 || res.statusCode >= 300)) {
+        reject(new Error(`Unexpected status code ${res.statusCode}`));
+        return;
