+ *
+ * @param {string} mediaUrl
+ * @param {{root?: string}} [options]
+ * @returns {Promise<Buffer>}
+ */
+async function loadMedia(mediaUrl, options = {}) {
+  if (!mediaUrl || typeof mediaUrl !== 'string') {
+    throw new Error('mediaUrl must be a non-empty string');
+  }
+
+  const root = options.root ? path.resolve(options.root) : process.cwd();
+
+  // HTTP(S)
+  if (/^https?:\/\//i.test(mediaUrl)) {
+    return fetchBuffer(mediaUrl);
+  }
+
+  // data: URLs
+  if (/^data:/i.test(mediaUrl)) {
+    // data:[<mediatype>][;base64],<data>
+    const m = mediaUrl.match(/^data:([^;]+)?(;base64)?,(.*)$/i);
+    if (!m) throw new Error('invalid data URL');
+    const isBase64 = !!m[2];
+    const raw = m[3] || '';
+    return Buffer.from(isBase64 ? raw : decodeURIComponent(raw), isBase64 ? 'base64' : 'utf8');
+  }
+
+  // file:// URLs
+  if (/^file:\/\//i.test(mediaUrl)) {
+    const u = new URL(mediaUrl);
+    return readLocalFile(decodeURIComponent(u.pathname), root);
+  }
+
+  // Treat everything else as a local path (relative or absolute).
+  return readLocalFile(mediaUrl, root);
+}
+
+async function readLocalFile(requestPath, root) {
+  // Resolve against root to get canonical path. Prepend './' for relative paths so that
+  // path.resolve(root, './rel/path') works as intended. If requestPath is absolute, the
+  // resolve will produce an absolute path which we will then check against root.
+  const candidate = path.resolve(root, './' + requestPath);
+
+  // Normalize root comparison to include trailing sep for prefix checks.
+  const rootWithSep = root.endsWith(path.sep) ? root : root + path.sep;
+
+  // Allow the resolved path to be exactly the root (reading a file that equals root is unlikely,
+  // but the check is here for correctness), or be a path under root.
+  if (candidate !== root && !candidate.startsWith(rootWithSep)) {
+    throw new Error('access denied: path outside of allowed root');
+  }
+
+  return fs.readFile(candidate);
+}
+
+function fetchBuffer(url) {
+  return new Promise((resolve, reject) => {
+    const lib = url.startsWith('https') ? https : http;
+    lib.get(url, (res) => {
+      if (res.statusCode && (res.statusCode < 200 || res.statusCode >= 300)) {
+        const err = new Error('Failed to fetch media: ' + res.statusCode);
+        err.status = res.statusCode;
+        res.resume();
+        return reject(err);
+      }
+      const bufs = [];
+      res.on('data', (c) => bufs.push(c));
+      res.on('end', () => resolve(Buffer.concat(bufs)));
+    }).on('error', reject);
+  });
