+import { RequestHandler } from 'express';
+
+/**
+ * Express middleware to protect against DNS rebinding by validating the Host header.
+ * If allowedHosts is provided it is used (case-insensitive) as the whitelist.
+ * If allowedHosts is not provided the middleware allows only localhost addresses:
+ *   - localhost
+ *   - 127.0.0.1
+ *   - ::1
+ */
+export function hostHeaderValidation(allowedHosts?: string[]): RequestHandler {
+  const allowedSet = new Set(
+    (allowedHosts || []).map((h) => String(h).toLowerCase())
+  );
+
+  const defaultAllowed = new Set(['localhost', '127.0.0.1', '::1']);
+
+  return (req, res, next) => {
+    const hostHeader = req.headers && req.headers.host;
+    if (!hostHeader || typeof hostHeader !== 'string') {
+      // No Host header — treat as bad request.
+      res.status(400).end('Bad Request');
+      return;
+    }
+
+    const host = hostHeader.split(':')[0].toLowerCase();
+
+    // If an explicit whitelist was provided use that, otherwise allow localhost addresses only.
+    const isAllowed =
+      allowedSet.size > 0 ? allowedSet.has(host) : defaultAllowed.has(host);
+
+    if (isAllowed) {
+      next();
+    } else {
+      // 400 is intentionally used to avoid leaking information; this stops requests from other origins.
+      res.status(400).end('Bad Request');
+    }
+  };
+}
