+// Fetch a remote URL and return a dataURL via callback(callbackErr, dataURL)
+// Added redirect limit to avoid unbounded redirect chasing (CWE-770).
+var MAX_EMBED_REDIRECTS = 10;
+
+function getDataUrlFromUrl(url, callback, redirectsLeft) {
+  if (typeof redirectsLeft === 'undefined') {
+    redirectsLeft = MAX_EMBED_REDIRECTS;
+  }
+
+  if (redirectsLeft <= 0) {
+    callback(new Error('Too many redirects while fetching resource: ' + url));
+    return;
+  }
+
+  var xhr = new XMLHttpRequest();
+  try {
+    xhr.open('GET', url);
+  } catch (e) {
+    callback(new Error('Invalid URL or unsupported protocol: ' + url));
+    return;
+  }
+  xhr.responseType = 'blob';
+  xhr.onload = function () {
+    if (xhr.status >= 200 && xhr.status < 300) {
+      var reader = new FileReader();
+      reader.onloadend = function () {
+        callback(null, reader.result);
+      };
+      reader.readAsDataURL(xhr.response);
+    } else if (xhr.status >= 300 && xhr.status < 400) {
+      // follow redirect (respecting a max redirect depth to prevent loops)
+      var location = xhr.getResponseHeader('Location') || xhr.getResponseHeader('location');
+      if (location) {
+        // resolve relative Location headers against the original URL
+        try {
+          var resolved = new URL(location, url).toString();
+          getDataUrlFromUrl(resolved, callback, redirectsLeft - 1);
+        } catch (e) {
+          callback(new Error('Invalid redirect Location header: ' + location));
+        }
+      } else {
+        callback(new Error('Redirect without Location header while fetching: ' + url));
+      }
+    } else {
+      callback(new Error('Failed to load resource: status ' + xhr.status));
+    }
+  };
+  xhr.onerror = function () {
+    callback(new Error('Network error while fetching ' + url));
+  };
