+import { spawnSync } from "child_process";
+import * as fs from "fs";
+import * as os from "os";
+import * as path from "path";
+
+/**
+ * Verify that the given packfile (as Buffer) does not introduce commit objects
+ * outside of the allowedCommits set.
+ *
+ * This function:
+ *  - writes the pack buffer to a temp dir
+ *  - runs `git index-pack --stdin` to generate a .pack/.idx pair in that temp dir
+ *  - runs `git verify-pack -v <idx>` to list objects in the pack and extract commit SHAs
+ *  - errors if any commit SHA from the pack is not present in allowedCommits
+ *
+ * Returns void on success, throws an Error on verification failure.
+ */
+export function verifyPackCommits(packBuffer: Buffer, allowedCommits: Set<string>): void {
+  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "git-proxy-pack-"));
+  try {
+    // Run `git index-pack --stdin` in the temp dir to materialize pack+idx there.
+    const idxResult = spawnSync("git", ["index-pack", "--index-version=2", "--stdin"], {
+      input: packBuffer,
+      cwd: tmpDir,
+      encoding: "utf8",
+    });
+
+    if (idxResult.status !== 0) {
+      // index-pack failed; do not trust the pack
+      throw new Error(
+        `pack verification failed (index-pack): ${idxResult.stderr || idxResult.stdout || idxResult.status}`
+      );
+    }
+
+    // Find the generated .idx file
+    const files = fs.readdirSync(tmpDir);
+    const idxFile = files.find((f) => f.endsWith(".idx"));
+    if (!idxFile) {
+      throw new Error("pack verification failed: .idx file not produced");
+    }
+    const idxPath = path.join(tmpDir, idxFile);
+
+    // Run `git verify-pack -v <idx>` and parse commit entries.
+    const verify = spawnSync("git", ["verify-pack", "-v", idxPath], {
+      cwd: tmpDir,
+      encoding: "utf8",
+    });
+    if (verify.status !== 0) {
+      throw new Error(
+        `pack verification failed (verify-pack): ${verify.stderr || verify.stdout || verify.status}`
+      );
+    }
+
+    // verify-pack -v output lines look like:
+    // <sha1> <type> <size> <packed_size> <offset>
+    // We consider lines where <type> === "commit".
+    const commitShas: string[] = [];
+    for (const line of verify.stdout.split(/\r?\n/)) {
+      if (!line.trim()) continue;
+      const parts = line.trim().split(/\s+/);
+      // Expect at least: sha type size ...
+      if (parts.length >= 2) {
+        const sha = parts[0];
+        const type = parts[1];
+        if (type === "commit") {
+          commitShas.push(sha);
+        }
+      }
+    }
+
+    // If any commit in the pack is not in the allowed set, reject.
+    const offending: string[] = [];
+    for (const sha of commitShas) {
+      if (!allowedCommits.has(sha)) {
+        offending.push(sha);
+      }
+    }
+    if (offending.length > 0) {
+      throw new Error(
+        `pack contains commit(s) not allowed by ref update: ${offending.join(", ")}`
+      );
+    }
+  } finally {
+    // best-effort cleanup of temp dir
+    try {
+      const items = fs.readdirSync(tmpDir);
+      for (const it of items) {
+        try {
+          fs.unlinkSync(path.join(tmpDir, it));
+        } catch {}
+      }
+      fs.rmdirSync(tmpDir);
+    } catch {}
+  }
