+/**
+ * Convert an Astro-style route (e.g. /foo/[p1]/bar/[p2]) into a RegExp.
+ *
+ * Security:
+ * - Prevent catastrophic backtracking by avoiding ambiguous nested quantifiers
+ *   such as '(.+)' across multiple params. Each param segment is limited to
+ *   match anything except a path separator ('/'), which both matches expected
+ *   param semantics and is safe for regex performance.
+ * - Escape static segments so that special regex chars in literal parts do
+ *   not change matching semantics.
+ */
+export function pathToRegex(route: string): RegExp {
+  // Split route into segments and convert each segment safely.
+  // Example: /foo/[p1]/bar/[p2] -> ^/foo/([^/]+)/bar/([^/]+)$
+  const segments = route.split('/').map((seg) => {
+    if (seg.startsWith('[') && seg.endsWith(']')) {
+      // Match one or more chars that are not '/', i.e. a single path segment.
+      // This avoids '.*' or '.+' which can cross slashes and cause backtracking.
+      return '([^/]+)';
+    }
+    // Escape regexp meta-characters in static segments.
+    return seg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+  });
+
+  // Preserve leading/trailing slashes from the original route.
+  const prefix = route.startsWith('/') ? '/' : '';
+  const suffix = route.endsWith('/') && route !== '/' ? '/' : '';
+  // Join only the mapped segments that are non-empty to avoid duplicating slashes.
+  const joined = segments.filter(Boolean).join('/');
+  const regexSource = `${prefix}${joined}${suffix}`;
+
+  return new RegExp(`^${regexSource}$`);
