+import * as vm from 'vm';
+
+/**
+ * Safely evaluate a user-supplied expression in a tightly controlled sandbox.
+ *
+ * Root cause of CVE-2025-68613: previously we used a plain object as the
+ * sandbox/context which allowed prototype traversal and access to dangerous
+ * globals (e.g. Function, process, require). This patch creates a null-
+ * prototype sandbox, copies only safe keys, removes dangerous names, and
+ * executes the script with a timeout to prevent long-running code.
+ */
+export function evaluateExpression(expression: string, context: IDataObject) {
+	// Names that must never be exposed to expressions.
+	const forbidden = new Set([
+		'constructor',
+		'__proto__',
+		'prototype',
+		'process',
+		'require',
+		'global',
+		'globalThis',
+		'Function',
+		'eval',
+	]);
+
+	// Build a sandbox with a null prototype so expressions can't reach Object.prototype.
+	const sandbox: Record<string, unknown> = Object.create(null);
+
+	// Only copy own enumerable properties and skip any forbidden names.
+	if (context && typeof context === 'object') {
+		for (const key of Object.keys(context as IDataObject)) {
+			if (forbidden.has(key)) continue;
+			// Disallow keys that could be used to access prototypes by name.
+			if (key.startsWith('__')) continue;
+			sandbox[key] = (context as IDataObject)[key];
+		}
+	}
+
+	// Explicitly ensure dangerous globals are not present on the sandbox.
+	for (const name of forbidden) {
+		// @ts-ignore - intentionally setting to undefined on a null-proto object
+		sandbox[name] = undefined;
+	}
+
+	// Prevent the evaluated code from accessing the real global by setting a strict global alias.
+	Object.defineProperty(sandbox, 'global', { value: undefined, configurable: false, enumerable: false });
+	Object.defineProperty(sandbox, 'globalThis', { value: undefined, configurable: false, enumerable: false });
+
+	// Create the context and run the script with a timeout to mitigate infinite loops.
+	const contextified = vm.createContext(sandbox, { name: 'n8n-expression-sandbox' });
+	const script = new vm.Script(expression);
+
+	// Use a reasonable timeout (in ms). Keep minimal to avoid breaking legitimate use.
+	const TIMEOUT = 1000;
+	return script.runInContext(contextified, { timeout: TIMEOUT });
