+/**
+ * Minimal HTML escaper to prevent injection when inserting user-controlled
+ * strings into HTML contexts. This is intentionally small and dependency-free.
+ *
+ * Note: We prefer to escape at render-time (output encoding) rather than
+ * mutating stored data. This utility is suitable for escaping values that
+ * will be placed into innerHTML/HTML templates used by chart tooltips, etc.
+ */
+export default function escapeHtml(input?: string | number | null): string {
+  if (input === null || input === undefined) {
+    return '';
+  }
+  const str = String(input);
+  // Replace characters with their HTML entity equivalents
+  return str
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;')
+    .replace(/'/g, '&#39;')
+    .replace(/\//g, '&#x2F;');
+}
